tools.usage:
#include "wstp.h"
WSENV env = WSInitialize(NULL);
WSLINK link = WSOpenArgcArgv(env, argc, argv, &err);
WSPutFunction(link, "EvaluatePacket", 1);
WSPutFunction(link, "Prime", 1); WSPutInteger64(link, 100);
WSEndPacket(link); WSFlush(link);
while (WSNextPacket(link) != RETURNPKT) WSNewPacket(link);
WSGetInteger64(link, &result);
WSClose(link); WSDeinitialize(env);
